<style>
.order-workspace{--order-border:#e2e8f0;--order-muted:#64748b;--order-panel:#fff;color:#17243b}.dark .order-workspace{--order-border:#334155;--order-muted:#a1afc2;--order-panel:rgb(var(--body-bg));color:#e2e8f0}.order-workspace .o-panel{background:var(--order-panel);border:1px solid var(--order-border);border-radius:12px;padding:1.2rem}.o-toolbar{display:flex;gap:.75rem;align-items:center;flex-wrap:wrap;margin-bottom:1rem}.o-title{font-size:1.45rem;font-weight:700;margin-right:auto}.o-muted{color:var(--order-muted);font-size:.85rem}.o-input{border:1px solid var(--order-border);border-radius:7px;padding:.55rem .7rem;background:var(--order-panel);color:inherit;max-width:100%}.o-error{background:#fff1f2;color:#9f1239;padding:1rem;border-radius:8px;margin-bottom:1rem}.o-grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(330px,1fr);gap:1rem}.o-products{display:grid;grid-template-columns:repeat(auto-fill,minmax(145px,1fr));gap:.7rem}.o-product{text-align:left;padding:1rem;border:1px solid var(--order-border);border-radius:10px;min-height:105px;display:flex;flex-direction:column;justify-content:space-between;gap:.7rem}.o-product:hover{border-color:#6366f1;background:#6366f10a}.o-categories{display:flex;gap:.5rem;overflow:auto;padding-bottom:1rem;white-space:nowrap}.o-chip{padding:.5rem .8rem;border:1px solid var(--order-border);border-radius:25px}.o-chip.active{background:#4f46e5;color:white;border-color:#4f46e5}.o-line{padding:.8rem 0;border-bottom:1px solid var(--order-border)}.o-row{display:flex;gap:.7rem;align-items:center;justify-content:space-between}.o-badge{display:inline-block;font-size:.75rem;font-weight:600;border-radius:20px;padding:.2rem .6rem;background:#eef2ff;color:#4338ca}.o-modal{position:fixed;inset:0;z-index:10000;background:#0f172a88;display:flex;align-items:center;justify-content:center;padding:1rem}.o-dialog{background:var(--order-panel);border-radius:12px;padding:1.5rem;width:600px;max-width:100%;max-height:90vh;overflow:auto}.o-field{display:block;margin:.9rem 0}.o-field>span{display:block;margin-bottom:.4rem;font-weight:600}.o-table{width:100%;border-collapse:collapse;text-align:left}.o-table th,.o-table td{padding:.8rem;border-bottom:1px solid var(--order-border);vertical-align:top}.o-table th{color:var(--order-muted);font-size:.8rem}.o-legend{display:flex;gap:1rem;flex-wrap:wrap;font-size:.8rem;margin:.7rem 0}.o-dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}.o-board{display:grid;grid-template-columns:repeat(4,minmax(230px,1fr));gap:1rem;overflow:auto}.o-ticket{background:var(--order-panel);border:1px solid var(--order-border);border-top:4px solid #6366f1;border-radius:10px;padding:1rem;margin:.8rem 0}.o-fullscreen:fullscreen{background:var(--order-panel);padding:1rem;overflow:auto}.o-empty{padding:2rem;text-align:center;color:var(--order-muted)}@media(max-width:900px){.o-grid{grid-template-columns:1fr}.o-products{grid-template-columns:repeat(2,minmax(0,1fr))}}@media print{.o-no-print{display:none!important}.o-panel{border:0!important}.o-table{font-size:11px}}
</style>
